package connect

import (
	"errors"
)

// ResultOf evaluates the provided board and returns the winner, if any.
//
// The board is a parallelogram of hexagonal cells, represented as a slice of
// strings in which every row holds the same number of cells. A cell is '.',
// 'X' or 'O'. Player "O" plays from top to bottom and player "X" plays from
// left to right; the first player whose stones connect the two opposite
// sides assigned to them wins.
func ResultOf(lines []string) (string, error) {
	if len(lines) == 0 {
		return "", nil
	}

	board := make([][]rune, len(lines))
	for i, line := range lines {
		if len(line) != len(lines[0]) {
			return "", errors.New("board rows must all have the same length")
		}
		board[i] = []rune(line)
		for _, c := range line {
			if c != '.' && c != 'X' && c != 'O' {
				return "", errors.New("board may only contain '.', 'X' and 'O'")
			}
		}
	}

	// X plays from left to right, O plays from top to bottom.
	if hasConnection(board, 'X',
		func(r, c int) bool { return c == 0 },
		func(r, c int) bool { return c == len(board[0])-1 }) {
		return "X", nil
	}
	if hasConnection(board, 'O',
		func(r, c int) bool { return r == 0 },
		func(r, c int) bool { return r == len(board) - 1 }) {
		return "O", nil
	}
	return "", nil
}

// hasConnection reports whether the given player has a chain of connected
// stones from any cell satisfying isStart to any cell satisfying isGoal.
func hasConnection(board [][]rune, player rune, isStart, isGoal func(r, c int) bool) bool {
	rows := len(board)
	cols := len(board[0])

	visited := make([][]bool, rows)
	for i := range visited {
		visited[i] = make([]bool, cols)
	}

	// The neighbors of a hexagonal cell (r, c) are its two horizontal
	// neighbors and the two cells diagonally below it in the next row.
	neighbors := [][2]int{{0, -1}, {0, 1}, {1, -1}, {1, 0}}

	queue := make([][2]int, 0, rows*cols)
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if board[r][c] == player && isStart(r, c) {
				visited[r][c] = true
				queue = append(queue, [2]int{r, c})
			}
		}
	}

	for len(queue) > 0 {
		r, c := queue[0][0], queue[0][1]
		queue = queue[1:]

		if isGoal(r, c) {
			return true
		}

		for _, d := range neighbors {
			nr, nc := r+d[0], c+d[1]
			if nr < 0 || nr >= rows || nc < 0 || nc >= cols {
				continue
			}
			if visited[nr][nc] || board[nr][nc] != player {
				continue
			}
			visited[nr][nc] = true
			queue = append(queue, [2]int{nr, nc})
		}
	}

	return false
}

